-- =============================================================================
-- anaBokra seed (DEV / `supabase db reset`). Idempotent (upserts).
-- Source: packages/content (catalog.json, careers.generated.json, instruments/*.json)
-- as of the content snapshot 1.0.0-draft. Production content is loaded by the
-- content importer (see supabase/README.md "Loading content"), NOT by this file.
--
-- NOTE: the two "sample" careers are published ONLY so the anon/public API has
-- data in dev. Their last_reviewed_at is a dev placeholder; every other career
-- stays `draft` until the psychologist's review (see root README open items).
-- =============================================================================

-- Settings / flags -----------------------------------------------------------
on conflict (key) do update set value = excluded.value, description = excluded.description;

on conflict (key) do nothing;

on conflict (id) do nothing;

-- Clusters -------------------------------------------------------------------
on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order;
-- Careers (all draft except the two dev samples) ---------------------------
on conflict (id) do update set
  cluster_id = excluded.cluster_id, name = excluded.name, description = excluded.description, tasks = excluded.tasks,
  onet_codes = excluded.onet_codes, is_proxy = excluded.is_proxy, proxy_note = excluded.proxy_note,
  holland_code = excluded.holland_code, job_zone = excluded.job_zone, traits = excluded.traits;
-- (status / last_reviewed_at are deliberately NOT overwritten on re-seed: editors own them)

-- Sample Egypt data (PLACEHOLDER numbers, draft: not public) ------------------
on conflict (career_id, country_code) do nothing;

-- Instruments (draft until the psychologist approves; activate with
--   update public.instrument_versions set status='active', approved_at=now(), published_at=now() where ...) ---
values ('abilities', '1.0.0-draft', 'abilities', $j${"id":"abilities","version":"1.0.0-draft","kind":"abilities","name":{"en":"What are you strong at?","ar":"إيه نقط قوتك؟"},"source":{"name":"Self-ratings: anaBokra (domains aligned to O*NET Abilities). Performance items: to be supplied from ICAR.","url":"https://icar-project.org","license":"Self-rating wording: anaBokra. ICAR items are public domain but distributed on registration — the psychologist registers and selects 16 items (4 per domain: verbal, numerical/letter-number, matrix reasoning, 3D rotation).","notes":"Until performance items are added, ability scores come from self-ratings only (basis = 'self'), which the UI should label as 'self-reported strengths'. creative and manual are self-rated only by design."},"selfRatingScale":{"min":1,"max":5,"labels":[{"en":"Much weaker than others my age","ar":"أضعف بكتير من اللي في سني"},{"en":"A bit weaker","ar":"أضعف شوية"},{"en":"About the same","ar":"زي اللي في سني"},{"en":"A bit stronger","ar":"أقوى شوية"},{"en":"Much stronger than others my age","ar":"أقوى بكتير من اللي في سني"}]},"selfRatings":[{"id":"ab_verbal_1","domain":"verbal","text":{"en":"Understanding what I read quickly","ar":"إني أفهم اللي بقراه بسرعة"}},{"id":"ab_verbal_2","domain":"verbal","text":{"en":"Explaining my ideas clearly in writing or speech","ar":"إني أوضّح أفكاري بوضوح كتابةً أو كلامًا"}},{"id":"ab_numerical_1","domain":"numerical","text":{"en":"Solving math problems","ar":"حل مسائل الرياضيات"}},{"id":"ab_numerical_2","domain":"numerical","text":{"en":"Working with numbers quickly and accurately","ar":"التعامل مع الأرقام بسرعة ودقة"}},{"id":"ab_logical_1","domain":"logical","text":{"en":"Spotting patterns and rules","ar":"إني ألاحظ الأنماط والقواعد"}},{"id":"ab_logical_2","domain":"logical","text":{"en":"Solving puzzles and logic problems","ar":"حل الألغاز والمسائل المنطقية"}},{"id":"ab_spatial_1","domain":"spatial","text":{"en":"Imagining how an object looks when it's rotated","ar":"إني أتخيل شكل أي حاجة لما تتلف"}},{"id":"ab_spatial_2","domain":"spatial","text":{"en":"Reading maps and finding my way","ar":"قراءة الخرايط ومعرفة الطريق"}},{"id":"ab_creative_1","domain":"creative","text":{"en":"Coming up with many ideas quickly","ar":"إني أطلع أفكار كتير بسرعة"}},{"id":"ab_creative_2","domain":"creative","text":{"en":"Coming up with original, unusual ideas","ar":"إني أطلع أفكار جديدة ومختلفة"}},{"id":"ab_manual_1","domain":"manual","text":{"en":"Building or fixing things with my hands","ar":"إني أبني أو أصلّح حاجات بإيدي"}},{"id":"ab_manual_2","domain":"manual","text":{"en":"Doing precise work with my fingers, like assembling small parts","ar":"الشغل الدقيق بصوابعي زي تركيب القطع الصغيرة"}}],"performance":[],"performanceWeight":0.7}$j$::jsonb, 'f35bce293a5ba9b9dab3a04bc8b42dc9281680f6379c6a698359327c3aeaa4ee', 'draft')
