  ('dentist', 'health', $j${"en":"Dentist","ar":"طبيب أسنان"}$j$::jsonb, $j${"en":"Examine, diagnose, and treat diseases, injuries, and malformations of teeth and gums. May treat diseases of nerve, pulp, and other dental tissues affecting oral hygiene and retention of teeth. May fit dental appliances or provide preventive care.","ar":""}$j$::jsonb, $j$[{"en":"Use masks, gloves, and safety glasses to protect patients and self from infectious diseases.","ar":""},{"en":"Administer anesthetics to limit the amount of pain experienced by patients during procedures.","ar":""},{"en":"Examine teeth, gums, and related tissues, using dental instruments, x-rays, or other diagnostic equipment, to evaluate dental health, diagnose diseases or abnormalities, and plan appropriate treatments.","ar":""},{"en":"Formulate plan of treatment for patient's teeth and mouth tissue.","ar":""},{"en":"Use dental air turbines, hand instruments, dental appliances, or surgical implements.","ar":""},{"en":"Design, make, or fit prosthodontic appliances, such as space maintainers, bridges, or dentures, or write fabrication instructions or prescriptions for denturists or dental technicians.","ar":""}]$j$::jsonb, '{"29-1021.00"}'::text[], false, null, 'IRS', 5, $j${"riasec":{"R":5.23,"I":5.48,"A":1.17,"S":4.41,"E":2,"C":3.71},"personality":{"extraversion":0.501,"agreeableness":0.578,"conscientiousness":0.79,"emotionalStability":0.623,"intellect":0.434},"personalityDistinct":{"extraversion":0.708,"agreeableness":0.828,"conscientiousness":0.903,"emotionalStability":0.85,"intellect":0.601},"values":{"achievement":0.935,"workingConditions":0.947,"recognition":0.944,"relationships":0.886,"support":0.154,"independence":0.996},"abilities":{"verbal":{"level":0.814,"importance":0.719},"numerical":{"level":0.74,"importance":0.47},"logical":{"level":0.984,"importance":0.781},"spatial":{"level":0.716,"importance":0.359},"creative":{"level":0.749,"importance":0.548},"manual":{"level":0.998,"importance":0.773}}}$j$: