  ('pharmacist', 'health', $j${"en":"Pharmacist","ar":"صيدلي"}$j$::jsonb, $j${"en":"Dispense drugs prescribed by physicians and other health practitioners and provide information to patients about medications and their use. May advise physicians and other health practitioners on the selection, dosage, interactions, and side effects of medications.","ar":""}$j$::jsonb, $j$[{"en":"Review prescriptions to assure accuracy, to ascertain the needed ingredients, and to evaluate their suitability.","ar":""},{"en":"Collaborate with other health care professionals to plan, monitor, review, or evaluate the quality or effectiveness of drugs or drug regimens, providing advice on drug applications or characteristics.","ar":""},{"en":"Work in hospitals or clinics or for Health Management Organizations (HMOs), dispensing prescriptions, serving as a medical team consultant, or specializing in specific drug therapy areas, such as oncology or nuclear pharmacotherapy.","ar":""},{"en":"Provide information and advice regarding drug interactions, side effects, dosage, and proper medication storage.","ar":""},{"en":"Provide specialized services to help patients manage conditions, such as diabetes, asthma, smoking cessation, or high blood pressure.","ar":""},{"en":"Analyze prescribing trends to monitor patient compliance and to prevent excessive usage or harmful interactions.","ar":""}]$j$::jsonb, '{"29-1051.00"}'::text[], false, null, 'ISC', 5, $j${"riasec":{"R":2.82,"I":5.67,"A":1.48,"S":4.88,"E":2.62,"C":4.56},"personality":{"extraversion":0.473,"agreeableness":0.695,"conscientiousness":0.84,"emotionalStability":0.576,"intellect":0.404},"personalityDistinct":{"extraversion":0.665,"agreeableness":0.922,"conscientiousness":0.966,"emotionalStability":0.78,"intellect":0.569},"values":{"achievement":0.572,"workingConditions":0.657,"recognition":0.944,"relationships":0.692,"support":0.84,"independence":0.526},"abilities":{"verbal":{"level":0.866,"importance":0.765},"numerical":{"level":0.858,"