  ('environmental_scientist', 'science', $j${"en":"Environmental Scientist","ar":"عالم بيئة"}$j$::jsonb, $j${"en":"Conduct research or perform investigation for the purpose of identifying, abating, or eliminating sources of pollutants or hazards that affect either the environment or public health. Using knowledge of various scientific disciplines, may collect, synthesize, study, report, and recommend action based on data derived from measurements or observations of air, food, soil, water, and other sources.","ar":""}$j$::jsonb, $j$[{"en":"Communicate scientific or technical information to the public, organizations, or internal audiences through oral briefings, written documents, workshops, conferences, training sessions, or public hearings.","ar":""},{"en":"Monitor effects of pollution or land degradation and recommend means of prevention or control.","ar":""},{"en":"Collect, synthesize, analyze, manage, and report environmental data, such as pollution emission measurements, atmospheric monitoring measurements, meteorological or mineralogical information, or soil or water samples.","ar":""},{"en":"Review and implement environmental technical standards, guidelines, policies, and formal regulations that meet all appropriate requirements.","ar":""},{"en":"Provide scientific or technical guidance, support, coordination, or oversight to governmental agencies, environmental programs, industry, or the public.","ar":""},{"en":"Process and review environmental permits, licenses, or related materials.","ar":""}]$j$::jsonb, '{"19-2041.00"}'::text[], false, null, 'IRC', 4, $j${"riasec":{"R":4.76,"I":7,"A":1.87,"S":2.75,"E":2.56,"C":4.32},"personality":{"extraversion":0.479,"agreeableness":0.46,"conscientiousness":0.728,"emotionalStability":0.361,"intellect":0.662},"personalityDistinct":{"extraversion":0.679,"agreeableness":0.68,"conscientiousness":0.764,"emotionalStability":0.46,"intellect":0.889},"values":{"achievement":0.652,"workingConditions":0.657,"recognition":0.807,"rela