  ('geologist', 'science', $j${"en":"Geologist","ar":"جيولوجي"}$j$::jsonb, $j${"en":"Study the composition, structure, and other physical aspects of the Earth. May use geological, physics, and mathematics knowledge in exploration for oil, gas, minerals, or underground water; or in waste disposal, land reclamation, or other environmental problems. May study the Earth's internal composition, atmospheres, and oceans, and its magnetic, electrical, and gravitational forces. Includes mineralogists, paleontologists, stratigraphers, geodesists, and seismologists.","ar":""}$j$::jsonb, $j$[{"en":"Locate and review research articles or environmental, historical, or technical reports.","ar":""},{"en":"Communicate geological findings by writing research papers, participating in conferences, or teaching geological science at universities.","ar":""},{"en":"Plan or conduct geological, geochemical, or geophysical field studies or surveys, sample collection, or drilling and testing programs used to collect data for research or application.","ar":""},{"en":"Prepare geological maps, cross-sectional diagrams, charts, or reports concerning mineral extraction, land use, or resource management, using results of fieldwork or laboratory research.","ar":""},{"en":"Analyze and interpret geological data, using computer software.","ar":""},{"en":"Investigate the composition, structure, or history of the Earth's crust through the collection, examination, measurement, or classification of soils, minerals, rocks, or fossil remains.","ar":""}]$j$::jsonb, '{"19-2042.00"}'::text[], false, null, 'IRC', 4, $j${"riasec":{"R":5.59,"I":7,"A":2.72,"S":2.24,"E":1.65,"C":4.16},"personality":{"extraversion":0.356,"agreeableness":0.247,"conscientiousness":0.679,"emotionalStability":0.239,"intellect":0.694},"personalityDistinct":{"extraversion":0.525,"agreeableness":0.345,"conscientiousness":0.617,"emotionalStability":0.239,"intellect":0.935},"values":{"achievement":0.741,"workingConditions":0.846,"recognition":