  ('egyptologist', 'science', $j${"en":"Archaeologist / Egyptologist","ar":"عالم آثار ومصريات"}$j$::jsonb, $j${"en":"Study the origin, development, and behavior of human beings. May study the way of life, language, or physical characteristics of people in various parts of the world. May engage in systematic recovery and examination of material evidence, such as tools or pottery remaining from past human cultures, in order to determine the history, customs, and living habits of earlier civilizations.","ar":""}$j$::jsonb, $j$[{"en":"Collect information and make judgments through observation, interviews, and review of documents.","ar":""},{"en":"Teach or mentor undergraduate and graduate students in anthropology or archeology.","ar":""},{"en":"Write about and present research findings for a variety of specialized and general audiences.","ar":""},{"en":"Plan and direct research to characterize and compare the economic, demographic, health care, social, political, linguistic, and religious institutions of distinct cultural groups, communities, and organizations.","ar":""},{"en":"Create data records for use in describing and analyzing social patterns and processes, using photography, videography, and audio recordings.","ar":""},{"en":"Train others in the application of ethnographic research methods to solve problems in organizational effectiveness, communications, technology development, policy making, and program planning.","ar":""}]$j$::jsonb, '{"19-3091.00"}'::text[], false, null, 'IAR', 5, $j${"riasec":{"R":3.99,"I":6.84,"A":4.21,"S":3.67,"E":1.63,"C":3.19},"personality":{"extraversion":0.476,"agreeableness":0.527,"conscientiousness":0.61,"emotionalStability":0.333,"intellect":0.784},"personalityDistinct":{"extraversion":0.673,"agreeableness":0.773,"conscientiousness":0.409,"emotionalStability":0.404,"intellect":0.995},"values":{"achievement":0.896,"workingConditions":0.794,"recognition":0.848,"relationships":0.596,"support":0.091,"independence":0.804},"abilities":{"v